export const BROCCOLI_PHONE_STYLES: string = "\n\n\n\n\n\n\n\n\n/* ============================================================\n   Broccoli \u2014 investor / launch deck\n   Built on the app's own design system (DESIGN.md):\n   precise, curved, poppy. Measured values are always mono.\n   ============================================================ */\n\n:host{\n  /* palette */\n  --bone:#EFEEE2;  --linen:#E2E1D1;  --loden:#1A1F14;\n  --moss:#4A5C2A;  --sprout:#B9D94A; --marigold:#E8A33C; --ember:#B0432A;\n  --lift:#3B462E;  --card-dark:#10130C; --moss-dark:#85A04E; --ember-dark:#E0674A;\n  --muted-l:#5B6549; --muted-d:#A2AA92;\n  --hair-l:rgba(26,31,20,.13); --hair-d:rgba(239,238,226,.15);\n\n  /* radii \u2014 nothing below 12 */\n  --r-xs:12px; --r-sm:18px; --r-md:26px; --r-lg:36px; --r-xl:52px; --r-pill:999px;\n\n  --display:'Bricolage Grotesque',system-ui,sans-serif;\n  --body:'Figtree',system-ui,sans-serif;\n  --mono:'Martian Mono',ui-monospace,monospace;\n}\n\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{background:#0b0d08}\nbody{font-family:var(--body);-webkit-font-smoothing:antialiased;\n  text-rendering:geometricPrecision}\n\n/* ---------- slide shell ---------- */\n.slide{\n  position:relative;width:1920px;height:1080px;overflow:hidden;\n  page-break-after:always;break-after:page;\n  background:var(--bone);color:var(--loden);\n  padding:88px 128px 86px;display:flex;flex-direction:column;\n}\n.slide:last-child{page-break-after:auto;break-after:auto}\n.slide.dark{background:var(--loden);color:var(--bone)}\n.slide.ink{background:var(--card-dark);color:var(--bone)}\n.slide.moss{background:var(--moss);color:var(--bone)}\n.slide.sprout{background:var(--sprout);color:var(--loden)}\n\n/* running chrome */\n.chrome{position:absolute;left:128px;right:128px;bottom:46px;\n  display:flex;justify-content:space-between;align-items:center;\n  font-family:var(--mono);font-size:15px;font-weight:500;letter-spacing:.1em;\n  text-transform:uppercase;color:var(--muted-l);}\n.dark .chrome,.ink .chrome{color:var(--muted-d)}\n.moss .chrome{color:rgba(239,238,226,.62)}\n.sprout .chrome{color:rgba(26,31,20,.55)}\n.chrome .mark{display:flex;align-items:center;gap:11px}\n.chrome .dot{width:11px;height:11px;border-radius:50%;background:var(--sprout)}\n.sprout .chrome .dot,.moss .chrome .dot{background:var(--bone)}\n\n/* eyebrow / section numbering */\n.eyebrow{font-family:var(--mono);font-size:17px;font-weight:700;\n  letter-spacing:.17em;text-transform:uppercase;color:var(--moss);\n  display:flex;align-items:center;gap:16px}\n.dark .eyebrow,.ink .eyebrow{color:var(--sprout)}\n.moss .eyebrow{color:var(--sprout)}\n.sprout .eyebrow{color:var(--moss)}\n.eyebrow::before{content:'';width:46px;height:3px;background:currentColor;\n  border-radius:2px;display:block;opacity:.85}\n.eyebrow.bare::before{display:none}\n\n/* ---------- type scale (golden-ratio, from DESIGN.md) ---------- */\nh1{font-family:var(--display);font-weight:800;letter-spacing:-.028em;\n  font-size:126px;line-height:.94}\nh2{font-family:var(--display);font-weight:800;letter-spacing:-.024em;\n  font-size:82px;line-height:1.02;max-width:20ch}\nh3{font-family:var(--display);font-weight:800;letter-spacing:-.018em;\n  font-size:46px;line-height:1.1}\nh4{font-family:var(--display);font-weight:800;letter-spacing:-.012em;\n  font-size:30px;line-height:1.2}\n.lede{font-size:31px;line-height:1.45;max-width:30ch;color:var(--muted-l);\n  font-weight:400}\n.dark .lede,.ink .lede{color:var(--muted-d)}\n.moss .lede{color:rgba(239,238,226,.82)}\n.sprout .lede{color:rgba(26,31,20,.72)}\np{font-size:23px;line-height:1.55}\n.small{font-size:19px;line-height:1.5}\n.tiny{font-size:16px;line-height:1.45}\nstrong{font-weight:700}\nem{font-style:normal;color:var(--moss);font-weight:600}\n.dark em,.ink em{color:var(--sprout)}\n\n.num{font-family:var(--mono);font-variant-numeric:tabular-nums;\n  font-feature-settings:\"tnum\" 1}\n.metric{font-family:var(--mono);font-weight:800;letter-spacing:-.04em;\n  font-size:104px;line-height:1}\n.readout{font-family:var(--mono);font-weight:800;letter-spacing:-.045em;\n  font-size:150px;line-height:.92}\n.unit{font-family:var(--mono);font-weight:500;font-size:22px;\n  letter-spacing:.08em;text-transform:uppercase;color:var(--muted-l)}\n.dark .unit,.ink .unit{color:var(--muted-d)}\n\n/* ---------- layout helpers ---------- */\n.row{display:flex;gap:64px}\n.col{display:flex;flex-direction:column}\n.grow{flex:1}\n.between{justify-content:space-between}\n.center{align-items:center}\n.gap-s{gap:24px}.gap-m{gap:40px}.gap-l{gap:64px}\n.mt-a{margin-top:auto}\n.head{margin-bottom:42px}\n.head h2{margin-top:26px}\n.head .lede{margin-top:24px;max-width:56ch;font-size:27px}\n\n/* cards */\n.card{background:#fff;border-radius:var(--r-lg);padding:40px 44px;\n  border:1.5px solid var(--hair-l)}\n.bone .card,.slide:not(.dark):not(.ink):not(.moss):not(.sprout) .card{\n  background:rgba(255,255,255,.72)}\n.dark .card,.ink .card{background:var(--lift);border-color:transparent}\n.moss .card{background:rgba(16,19,12,.30);border-color:rgba(239,238,226,.18)}\n.sprout .card{background:rgba(255,255,255,.55);border-color:rgba(26,31,20,.14)}\n.card.outline{background:transparent;border:2px solid var(--hair-l)}\n.dark .card.outline,.ink .card.outline{border-color:var(--hair-d)}\n\n.tag{font-family:var(--mono);font-size:14px;font-weight:700;letter-spacing:.13em;\n  text-transform:uppercase;padding:9px 16px;border-radius:var(--r-pill);\n  background:var(--linen);color:var(--moss);display:inline-block}\n.dark .tag,.ink .tag{background:var(--lift);color:var(--sprout)}\n.tag.solid{background:var(--sprout);color:var(--loden)}\n.tag.amber{background:var(--marigold);color:var(--loden)}\n\nhr{border:0;height:1.5px;background:var(--hair-l);margin:0}\n.dark hr,.ink hr{background:var(--hair-d)}\n\n/* ---------- the tolerance bar, the brand's signature mark ---------- */\n.tbar{position:relative;height:56px;border-radius:var(--r-pill);\n  background:var(--linen);overflow:hidden;display:flex}\n.dark .tbar,.ink .tbar{background:var(--lift)}\n.tbar span{height:100%;display:block}\n.tbar .weighed{background:var(--sprout)}\n.tbar .est{background:var(--marigold)}\n.tbar .typed{background:repeating-linear-gradient(-45deg,\n  var(--marigold) 0 5px,transparent 5px 11px);\n  box-shadow:inset 0 0 0 2px var(--marigold)}\n.tbar .fade{background:linear-gradient(90deg,var(--sprout),rgba(185,217,74,0))}\n.tbar.sm{height:30px}\n.tbar.xs{height:18px}\n.notch{position:absolute;top:-8px;bottom:-8px;width:4px;background:var(--loden);\n  border-radius:2px}\n.dark .notch,.ink .notch{background:var(--bone)}\n\n.legend{display:flex;gap:40px;font-size:19px;align-items:center;\n  color:var(--muted-l);font-weight:500}\n.dark .legend,.ink .legend{color:var(--muted-d)}\n.legend i{width:17px;height:17px;border-radius:5px;display:inline-block;\n  margin-right:11px;vertical-align:-2px}\n.legend .w{background:var(--sprout)}\n.legend .e{background:var(--marigold)}\n.legend .t{border:2px dashed var(--marigold);background:transparent}\n\n/* ---------- phone frame ---------- */\n.phone{width:372px;height:790px;border-radius:52px;background:var(--loden);\n  padding:9px;position:relative;flex:none;\n  box-shadow:0 44px 90px -30px rgba(10,14,7,.55),0 0 0 1.5px rgba(239,238,226,.10)}\n.phone.lt{background:#2a3120}\n.phone .screen{width:100%;height:100%;border-radius:44px;overflow:hidden;\n  background:var(--loden);color:var(--bone);position:relative;\n  display:flex;flex-direction:column}\n.phone .screen.light{background:var(--bone);color:var(--loden)}\n.phone .sbar{height:34px;display:flex;align-items:center;justify-content:space-between;\n  padding:0 22px 0 26px;font-family:var(--mono);font-size:11px;font-weight:700;\n  flex:none;opacity:.9}\n.phone .sbar .sig{display:flex;gap:5px;align-items:center}\n.phone .sbar .sig b{display:block;width:13px;height:11px;border-radius:2px;\n  background:currentColor}\n.phone .body{flex:1;padding:0 20px;overflow:hidden}\n.phone .home{height:5px;width:120px;border-radius:3px;background:currentColor;\n  opacity:.5;margin:0 auto 9px}\n.phone-cap{font-family:var(--mono);font-size:15px;font-weight:700;\n  letter-spacing:.13em;text-transform:uppercase;color:var(--muted-l);\n  text-align:center;margin-top:26px}\n.dark .phone-cap,.ink .phone-cap{color:var(--muted-d)}\n\n/* in-phone primitives */\n.p-h{font-family:var(--display);font-weight:800;letter-spacing:-.02em}\n.p-mono{font-family:var(--mono);font-variant-numeric:tabular-nums}\n.p-card{border-radius:22px;padding:14px 16px}\n.p-muted{color:var(--muted-d)}\n.light .p-muted{color:var(--muted-l)}\n\n/* ---------- misc marks ---------- */\n.coin{width:74px;height:74px;border-radius:50%;background:var(--bone);\n  display:flex;align-items:center;justify-content:center;flex:none;\n  box-shadow:inset 0 0 0 2px rgba(26,31,20,.12)}\n.rule-l{border-left:3px solid var(--sprout);padding-left:28px}\n.kv{display:flex;justify-content:space-between;align-items:baseline;\n  padding:19px 0;border-top:1.5px solid var(--hair-l)}\n.dark .kv,.ink .kv{border-color:var(--hair-d)}\n.kv:first-child{border-top:0}\n.kv .k{font-size:21px;font-weight:500}\n.kv .v{font-family:var(--mono);font-weight:700;font-size:21px}\n\n.stat{display:flex;flex-direction:column;gap:8px}\n.stat .f{font-family:var(--mono);font-weight:800;font-size:66px;line-height:1;\n  letter-spacing:-.04em}\n.stat .l{font-size:18px;font-weight:500;color:var(--muted-l);max-width:15ch;\n  line-height:1.35}\n.dark .stat .l,.ink .stat .l{color:var(--muted-d)}\n\n.pagenum{font-family:var(--mono);font-weight:700}\n\n/* hatch field used behind hero art */\n.hatch{background-image:repeating-linear-gradient(-45deg,\n  rgba(26,31,20,.055) 0 2px,transparent 2px 13px)}\n.dark .hatch,.ink .hatch{background-image:repeating-linear-gradient(-45deg,\n  rgba(239,238,226,.07) 0 2px,transparent 2px 13px)}\n\n@page{size:1920px 1080px;margin:0}\n\n/* gallery phones */\n.phone.sm{zoom:.755}\n.phone.xs{zoom:.62}\n\n    .kk{background:#1A1F14;border-radius:14px;height:38px;display:flex;\n      align-items:center;justify-content:center;font-family:var(--mono);\n      font-size:17px;font-weight:700;color:#EFEEE2}\n    .kk.sub{background:#2A3220;color:#A2AA92;font-size:15px}\n  \n    .dd{background:#E2E1D1;color:#5B6549;border-radius:8px;text-align:center;\n      font-family:var(--mono);font-size:11px;font-weight:700;padding:5px 0}\n    .dd.on{background:#B9D94A;color:#1A1F14}\n    .shelfcoin{width:42px;height:42px;border-radius:50%;background:#EFEEE2;\n      box-shadow:inset 0 0 0 1.5px rgba(26,31,20,.14);display:flex;\n      align-items:center;justify-content:center;flex:none}\n    .shelfcoin i{display:block}\n    .shelfcoin.dim{opacity:.34}\n  .cc{width:32px;height:32px;border-radius:50%;background:#E2E1D1;\n    display:flex;align-items:center;justify-content:center;flex:none}\n    .cc i{display:block}\n    .rf{display:flex;gap:22px;align-items:flex-start;padding:16px 0;\n      border-top:1.5px solid rgba(239,238,226,.15)}\n    .rf:first-child{border-top:0;padding-top:0}\n    .rf span{font-family:var(--mono);font-size:15px;font-weight:800;\n      color:var(--sprout);padding-top:4px;flex:none}\n    .rf p{font-size:21px;line-height:1.4;font-weight:500}\n  \n    .t-ch{font-family:var(--mono);font-size:15px;font-weight:700;letter-spacing:.08em;\n      text-transform:uppercase;color:var(--muted-l);padding:0 0 18px;\n      text-align:center;line-height:1.5}\n    .t-rl{font-size:18px;padding:12px 20px 12px 0;border-top:1.5px solid var(--hair-l);\n      font-weight:500}\n    .t-cy,.t-cn,.t-cx,.t-cb{text-align:center;font-size:16px;padding:12px 8px;\n      border-top:1.5px solid var(--hair-l);font-family:var(--body)}\n    .t-cy{color:var(--moss);font-weight:600}\n    .t-cn{color:var(--muted-l)}\n    .t-cx{color:var(--ember);font-weight:600}\n    .t-cb{color:var(--loden);font-weight:700;background:rgba(185,217,74,.20)}\n    tbody tr:last-child .t-cb{border-bottom-left-radius:18px;\n      border-bottom-right-radius:18px}\n    tbody tr:first-child .t-cb{border-top-left-radius:18px;\n      border-top-right-radius:18px}\n  \n.phone,.phone.sm,.phone.xs{zoom:1!important;box-shadow:0 0 0 1.5px rgba(239,238,226,.12)!important}\n@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}\n.live .body>*{animation:rise .7s cubic-bezier(.2,0,0,1) both;animation-delay:calc(var(--i,0)*80ms)}\n@media(prefers-reduced-motion:reduce){.live .body>*{animation:none}}";

